/// <summary>Typed resolver for the instrument dimension over a loaded (possibly customized)
/// vocabulary — the matching engine stays Dimension.Resolve; this is a thin typed projection.</summary>
public sealed class InstrumentView
{
    private readonly Dimension _dim;
    private readonly string _delimiter;

    /// <summary>Wrap a runtime dimension; <paramref name="delimiter"/> is the multi-value separator.</summary>
    public InstrumentView(Dimension dimension, string delimiter = "; ")
    {
        _dim = dimension;
        _delimiter = string.IsNullOrEmpty(delimiter) ? "; " : delimiter;
    }

    /// <summary>The generic (not-in-catalog) instrument term.</summary>
    public Instrument Generic => Instruments.Generic;

    /// <summary>Resolve one token; a miss returns the generic carrying the raw text. Never null.</summary>
    public InstrumentValue Resolve(string token)
    {
        var term = _dim.Resolve(token);
        if (term is null) return new InstrumentValue(Instruments.Generic, token);
        var hit = Instruments.ById.TryGetValue(term.Id, out var c) ? c : Instruments.FromTerm(term);
        return new InstrumentValue(hit, token);
    }

    /// <summary>Read a whole (multi-value) frame: per-value occurrences + the exact original frame.</summary>
    public InstrumentField Read(string? rawFrame)
    {
        var frame = rawFrame ?? "";
        var values = new List<InstrumentValue>();
        foreach (var part in frame.Split([_delimiter], System.StringSplitOptions.None))
        {
            var token = part.Trim();
            if (token.Length == 0) continue;
            values.Add(Resolve(token));
        }
        return new InstrumentField(values, frame);
    }
}

